def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    winners_est = max(1, int(supply / WATER_REQ))

    prev_bids = []
    named_prev = {}
    dangerous_count = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            named_prev[oid] = float(bid)
            if float(bid) >= 120:
                dangerous_count += 1

    bob_bid = named_prev.get('Bob', 75.0)
    eric_bid = named_prev.get('Eric', 130.0)
    cindy_bid = named_prev.get('Cindy', 0.0)

    active_threats = 0
    for oid, opp in alive:
        if opp.get('budget', 0) > 0:
            active_threats += 1

    if hp <= 2 or no_water >= 2:
        emergency = max(bob_bid + 8.0, 118.0)
        if eric_bid < 125:
            emergency = max(emergency, eric_bid + 3.0)
        return float(min(budget, emergency))

    if winners_est >= 2:
        base = bob_bid + 2.5
        if active_threats <= 2:
            base = min(base, 72.0)
        if hp >= 6 and no_water == 0 and dangerous_count >= 1:
            base = min(base, 68.0)
        if hp <= 4 or no_water == 1:
            base = max(base, bob_bid + 5.0)
        return float(min(budget, max(18.0, base)))

    scarce_bid = max(bob_bid + 7.0, 86.0)
    if eric_bid <= 110:
        scarce_bid = max(scarce_bid, eric_bid + 2.0)
    if hp >= 6 and no_water == 0 and eric_bid >= 125:
        scarce_bid = min(scarce_bid, 92.0)
    if hp <= 4 or no_water == 1:
        scarce_bid = max(scarce_bid, 96.0)
    if cindy_bid > 0 and cindy_bid < 90:
        scarce_bid = max(scarce_bid, cindy_bid + 3.0)

    return float(min(budget, scarce_bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive.append((oid, o))
        except Exception:
            continue

    # If no opponents alive, take a safe amount
    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday trace bids for immediate reaction
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass
        elif isinstance(prev, list):
            # Only immediate reaction: take last entry if present
            if len(prev) > 0:
                last = prev[-1]
                if isinstance(last, dict):
                    b = last.get('bid', None)
                    if b is not None:
                        try:
                            prev_bids.append(float(b))
                        except Exception:
                            pass

    # Estimate competitive pressure from yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base target bid: aim to win enough water while avoiding Cindy-like overbidding
    # Supply-dependent aggressiveness
    # More supply => lower bid needed; less supply => bid closer to salary
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # If I'm low HP, bid more to secure water
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # No-water days increases urgency
    no_water_days = int(my_status['no_water_days'])
    urgency = 0
    if no_water_days >= 2:
        urgency = 2
    elif no_water_days == 1:
        urgency = 1

    # Determine a cap to avoid runaway spending
    # If Cindy overbid yesterday, highest_prev_bid will be huge; we don't want to match it.
    # We'll use a fraction of highest_prev_bid unless I'm in danger.
    danger = (hp <= 2.5) or (urgency >= 2)

    if danger:
        # Near-critical: bid high but still below extreme bids
        target = DAILY_SALARY * (0.75 + 0.1 * urgency)
        # If someone already bid extremely high yesterday, don't fully mirror; still avoid wasting budget
        if highest_prev_bid > DAILY_SALARY * 1.5:
            target = min(target, highest_prev_bid * 0.35)
    else:
        # Normal: bid moderate; react to competition
        # If yesterday someone bid very high, slightly increase to avoid losing water.
        if highest_prev_bid >= DAILY_SALARY * 1.2:
            target = DAILY_SALARY * (0.55 + 0.15 * (1.0 - supply_ratio))
            target = min(target, highest_prev_bid * 0.25)
        else:
            target = DAILY_SALARY * (0.45 + 0.10 * (1.0 - supply_ratio))

    # Ensure we don't bid above our budget
    bid = float(min(budget, target))

    # If budget is tiny, still bid what we can
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0) 

    base_bid = DAILY_SALARY * 0.6 

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95 
    elif my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.85 
    elif my_status['hp'] <= 8:
        base_bid = DAILY_SALARY * 0.7 

    if day_context['day'] >= EPISODE_DAYS / 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.75)
        if my_status['hp'] <= 5:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)

        if day_context['supply'] < (WATER_REQ * (num_alive_opponents + 1)):
            if my_status['hp'] < 10: 
                base_bid = max(base_bid, max_prev_bid + 5.0) 
            else:
                base_bid = max(base_bid, max_prev_bid + 1.0) 
        else:
            if my_status['hp'] < 10:
                base_bid = max(base_bid, max_prev_bid * 1.05) 
            else:
                base_bid = min(base_bid, max(max_prev_bid * 0.9, DAILY_SALARY * 0.4)) 

    if my_status['hp'] < 10 and my_status['budget'] > 0:
        base_bid = max(base_bid, DAILY_SALARY * 0.1) 

    final_bid = min(my_status['budget'], base_bid)

    if final_bid == 0 and my_status['budget'] > 0 and my_status['hp'] < 10:
        final_bid = 1.0

    return final_bid

